57	    if (this.cachedSecretKey) {
58	      return this.cachedSecretKey;
59	    }
60	
61	    if (await this.keychainService.isAvailable()) {
62	      try {
63	        this.cachedSecretKey = await this.getSecretKeyFromKeychain();
64	        return this.cachedSecretKey;
65	      } catch (e) {
