30	export async function updateExtension(
31	  extension: GeminiCLIExtension,
32	  extensionManager: ExtensionManager,
33	  currentState: ExtensionUpdateState,
34	  dispatchExtensionStateUpdate: (action: ExtensionUpdateAction) => void,
35	  enableExtensionReloading?: boolean,
36	): Promise<ExtensionUpdateInfo | undefined> {
37	  if (currentState === ExtensionUpdateState.UPDATING) {
38	    return undefined;
39	  }
40	  dispatchExtensionStateUpdate({
41	    type: 'SET_STATE',
42	    payload: { name: extension.name, state: ExtensionUpdateState.UPDATING },
43	  });
44	  const installMetadata = loadInstallMetadata(extension.path);
45	
46	  if (!installMetadata?.type) {
47	    dispatchExtensionStateUpdate({
48	      type: 'SET_STATE',
49	      payload: { name: extension.name, state: ExtensionUpdateState.ERROR },
50	    });
51	    throw new Error(
52	      `Extension ${extension.name} cannot be updated, type is unknown.`,
53	    );
54	  }
55	
56	  try {
57	    const status = await extensionManager.verifyExtensionIntegrity(
58	      extension.name,
59	      installMetadata,
60	    );
61	
62	    if (status === IntegrityDataStatus.INVALID) {
63	      throw new Error('Extension integrity cannot be verified');
64	    }
65	  } catch (e) {
66	    dispatchExtensionStateUpdate({
67	      type: 'SET_STATE',
68	      payload: { name: extension.name, state: ExtensionUpdateState.ERROR },
69	    });
70	    throw new Error(
71	      `Extension ${extension.name} cannot be updated. ${getErrorMessage(e)}. To fix this, reinstall the extension.`,
72	    );
73	  }
74	
75	  if (installMetadata?.type === 'link') {
76	    dispatchExtensionStateUpdate({
77	      type: 'SET_STATE',
78	      payload: { name: extension.name, state: ExtensionUpdateState.UP_TO_DATE },
79	    });
80	    throw new Error(`Extension is linked so does not need to be updated`);
81	  }
82	
83	  if (extension.migratedTo) {
84	    const migratedState = await checkForExtensionUpdate(
85	      {
86	        ...extension,
87	        installMetadata: { ...installMetadata, source: extension.migratedTo },
88	        migratedTo: undefined,
89	      },
90	      extensionManager,
91	    );
92	    if (
93	      migratedState === ExtensionUpdateState.UPDATE_AVAILABLE ||
94	      migratedState === ExtensionUpdateState.UP_TO_DATE
95	    ) {
96	      installMetadata.source = extension.migratedTo;
97	    }
98	  }
99	
100	  const originalVersion = extension.version;
101	
102	  const tempDir = await ExtensionStorage.createTmpDir();
103	  try {
104	    const previousExtensionConfig = await extensionManager.loadExtensionConfig(
105	      extension.path,
106	    );
107	    let updatedExtension: GeminiCLIExtension;
108	    try {
109	      updatedExtension = await extensionManager.installOrUpdateExtension(
110	        installMetadata,
111	        previousExtensionConfig,
112	      );
113	    } catch (e) {
114	      dispatchExtensionStateUpdate({
115	        type: 'SET_STATE',
116	        payload: { name: extension.name, state: ExtensionUpdateState.ERROR },
117	      });
118	      throw new Error(
119	        `Updated extension not found after installation, got error:\n${e}`,
120	      );
121	    }
122	    const updatedVersion = updatedExtension.version;
123	    dispatchExtensionStateUpdate({
124	      type: 'SET_STATE',
125	      payload: {
126	        name: extension.name,
127	        state: enableExtensionReloading
128	          ? ExtensionUpdateState.UPDATED
129	          : ExtensionUpdateState.UPDATED_NEEDS_RESTART,
130	      },
131	    });
132	    return {
133	      name: extension.name,
134	      originalVersion,
135	      updatedVersion,
136	    };
137	  } catch (e) {
138	    debugLogger.error(
139	      `Error updating extension, rolling back. ${getErrorMessage(e)}`,
140	    );
141	    dispatchExtensionStateUpdate({
142	      type: 'SET_STATE',
143	      payload: { name: extension.name, state: ExtensionUpdateState.ERROR },
144	    });
145	    await copyExtension(tempDir, extension.path);
146	    throw e;
147	  } finally {
148	    await fs.promises.rm(tempDir, { recursive: true, force: true });
149	  }
150	}
