152	export async function updateAllUpdatableExtensions(
153	  extensions: GeminiCLIExtension[],
154	  extensionsState: Map<string, ExtensionUpdateStatus>,
155	  extensionManager: ExtensionManager,
156	  dispatch: (action: ExtensionUpdateAction) => void,
157	  enableExtensionReloading?: boolean,
158	): Promise<ExtensionUpdateInfo[]> {
159	  const results = await Promise.all(
160	    extensions
161	      .filter(
162	        (extension) =>
163	          extensionsState.get(extension.name)?.status ===
164	          ExtensionUpdateState.UPDATE_AVAILABLE,
165	      )
166	      .map((extension) =>
167	        updateExtension(
168	          extension,
169	          extensionManager,
170	          extensionsState.get(extension.name)!.status,
171	          dispatch,
172	          enableExtensionReloading,
173	        ),
174	      ),
175	  );
176	  return results.filter(
177	    (updateInfo): updateInfo is ExtensionUpdateInfo => !!updateInfo,
178	  );
179	}
