186	export async function checkForAllExtensionUpdates(
187	  extensions: GeminiCLIExtension[],
188	  extensionManager: ExtensionManager,
189	  dispatch: (action: ExtensionUpdateAction) => void,
190	): Promise<void> {
191	  dispatch({ type: 'BATCH_CHECK_START' });
192	  try {
193	    const promises: Array<Promise<void>> = [];
194	    for (const extension of extensions) {
195	      if (!extension.installMetadata) {
196	        dispatch({
197	          type: 'SET_STATE',
198	          payload: {
199	            name: extension.name,
200	            state: ExtensionUpdateState.NOT_UPDATABLE,
201	          },
202	        });
203	        continue;
204	      }
205	      dispatch({
206	        type: 'SET_STATE',
207	        payload: {
208	          name: extension.name,
209	          state: ExtensionUpdateState.CHECKING_FOR_UPDATES,
210	        },
211	      });
212	      promises.push(
213	        checkForExtensionUpdate(extension, extensionManager).then((state) =>
214	          dispatch({
215	            type: 'SET_STATE',
216	            payload: { name: extension.name, state },
217	          }),
218	        ),
219	      );
220	    }
221	    await Promise.all(promises);
222	  } finally {
223	    dispatch({ type: 'BATCH_CHECK_END' });
224	  }
225	}
